  ('D10-GOV-01', 'DAY10_CHECK', 'MULTIPLE_CHOICE', 'GOVERNANCE', 'Code of conduct', 'easy', 'A customer buyer offers you a gift worth about ₹12,000 after a meeting. What does the code of conduct require?',
   '[{"id":"a","text":"Accept it if your manager is copied"},{"id":"b","text":"Declare it to Compliance; it is normally declined"},{"id":"c","text":"Accept it, gifts from customers are allowed"},{"id":"d","text":"Share it with the team"}]'::jsonb, '{"value":"b"}'::jsonb, 'Gifts above the nominal ₹5,000 value must be declared to Compliance and are normally declined.', 1, 'Code of Conduct', 'Section 1, v6.0', 1),
  ('D10-PRD-03', 'DAY10_CHECK', 'MULTIPLE_CHOICE', 'PRODUCT', 'BEV', 'easy', 'Which FirstGear product belongs to the BEV technology family?',
