insert into public.scenario_templates (code, title, category, pillar, situation, prompt, rubric, red_flags,
  is_certification, requires_review, source_document, sort_order) values
  ('SCN-RFQ', 'RFQ response', 'RFQ', 'PROCESS', 'Northwind''s powertrain buyer sends an RFQ for EV differential assemblies with final-drive gear on the next-gen BEV platform. Drawings are attached but annual volumes and the SOP date are missing. The buyer asks for ''a ballpark price by Friday''.', 'Describe exactly how you respond to the buyer and what you do internally over the next five working days.',
   '[{"id":"log","criterion":"Log and acknowledge","description":"Logs the RFQ and acknowledges within two working days","weight":15,"keywords":["log","crm","acknowledge","rfq number"]},{"id":"clarify","criterion":"Clarify missing inputs","description":"Requests missing volumes / SOP date in writing","weight":20,"keywords":["volume","sop date","clarification","missing","clarify"]},{"id":"feasibility","criterion":"Feasibility before price","description":"Runs a cross-functional feasibility review before any price","weight":25,"keywords":["feasibility","engineering","plant","scm","go/no-go","no-go"],"min_matches":2},{"id":"no-ballpark","criterion":"No verbal / ballpark price","description":"Declines to give a ballpark price before approval","weight":25,"keywords":["no ballpark","not give a ballpark","cannot give a price","can''t give a price","no indicative","after approval","not quote verbally","won''t give a price","will not give a price"]},{"id":"approval","criterion":"Approval chain","description":"Routes the quotation through the approval chain","weight":15,"keywords":["approval","head of key accounts","cfo","approve"]}]'::jsonb, '[{"id":"ballpark-given","label":"Gives a ballpark/verbal price","patterns":["ballpark is","roughly ₹","around ₹","approximately ₹","price will be about"],"penalty":25}]'::jsonb, true, true, 'RFQ to Quotation SOP', 1),
  ('SCN-COSTING', 'Costing challenge', 'Costing', 'PROCESS', 'In a mock RFQ review, the buyer says your conversion cost looks 15% too high compared with ''the market'' and asks you to explain your cost build-up.', 'How do you explain the cost build-up and respond to the challenge? (Knowledge practice — no live pricing.)',
   '[{"id":"elements","criterion":"Explains cost elements","description":"Material, conversion, overheads, logistics, margin","weight":30,"keywords":["material","conversion","overhead","logistics","margin"],"min_matches":3},{"id":"evidence","criterion":"Uses documented inputs","description":"Cycle time / plant inputs / documented basis","weight":25,"keywords":["cycle time","documented","input","basis","evidence"]},{"id":"finance","criterion":"Involves Finance","description":"Analyses with Finance before responding","weight":20,"keywords":["finance","cost model"]},{"id":"no-concession","criterion":"No concession in the room","description":"Takes the ask back rather than conceding","weight":25,"keywords":["take back","come back","not concede","no concession","revert","approval"]}]'::jsonb, '[{"id":"unapproved-price","label":"Commits to a price, discount or terms without recorded approval","patterns":["i will give","we will give","i agree to","we agree to reduce","i can offer a","i approve","accept the reduction","agree to the discount"],"penalty":25}]'::jsonb, false, false, 'Costing and Commercial Mechanics Guide', 2),
  ('SCN-PRICE', 'Price challenge', 'Pricing', 'PROCESS', 'At the monthly review, Northwind''s Head of Powertrain Purchasing demands an additional 4% price-down on differential assemblies, on top of the 2% annual reduction, citing supplier consolidation.', 'How do you handle the demand in the meeting and afterwards?',
   '[{"id":"listen","criterion":"Capture the ask","description":"Listens, captures the ask in writing","weight":15,"keywords":["listen","capture","in writing","understand","note"]},{"id":"no-concede","criterion":"No concession in the meeting","description":"Does not concede in the room","weight":25,"keywords":["not concede","no concession","cannot agree","can''t agree","take it back","come back","revert"]},{"id":"analysis","criterion":"Analyse with Finance","description":"Uses cost breakdown and index data","weight":20,"keywords":["finance","cost breakdown","index","analysis","analyse","analyze"]},{"id":"givegets","criterion":"Position with give-gets","description":"Prepares a position with give-gets (volume, term, Project Aster)","weight":20,"keywords":["give-get","give get","in return","volume","aster","long-term","position"]},{"id":"approval","criterion":"Right approval level","description":"Beyond ±2% needs CFO approval","weight":20,"keywords":["cfo","approval","approval matrix","reporting boss","head of key accounts"]}]'::jsonb, '[{"id":"unapproved-price","label":"Commits to a price, discount or terms without recorded approval","patterns":["i will give","we will give","i agree to","we agree to reduce","i can offer a","i approve","accept the reduction","agree to the discount"],"penalty":25}]'::jsonb, true, true, 'Customer Escalation Playbook', 3),
  ('SCN-DELIVERY', 'Delivery-risk escalation', 'Delivery', 'PROCESS', 'A critical forging press on the differential-gear line has failed. SCM estimates 40% of next week''s Northwind shipment is at risk. The customer has not been told.', 'What do you do in the next 24 hours?',
